def minTransfers(transactions: list[list[int]]) -> int:
    from collections import defaultdict
    bal = defaultdict(int)
    for u, v, amt in transactions:
        bal[u] -= amt
        bal[v] += amt
    debts = [v for v in bal.values() if v != 0]
    def dfs(idx):
        while idx < len(debts) and debts[idx] == 0:
            idx += 1
        if idx == len(debts): return 0
        res = float('inf')
        for j in range(idx + 1, len(debts)):
            if debts[idx] * debts[j] < 0:
                debts[j] += debts[idx]
                res = min(res, 1 + dfs(idx + 1))
                debts[j] -= debts[idx]
        return res
    return dfs(0)

